SELECT /* LGVATT20552.retrieveSwapMaster */ sh.request_no AS request_no ,sh.request_seq_no AS request_seq_no ,em.organization_id AS employee_org ,sh.employee_no AS employee_no ,em.full_name_local AS employee_name ,sh.time_attend_input_reason_desc AS time_attend_input_reason_desc ,lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE' ,em.grade_title ,NULL ,#{USER_SESSION.languageCode}) AS employee_grade ,sh.shift_type_code ,TO_CHAR(sh.weekly_holiday, 'DD/MM/YYYY') AS weekly_holiday ,sh.weekly_holiday_shift_type_code ,(select t.shift_type_code from tb_att_result_n t where t.subsidiary_code = sh.subsidiary_code and t.time_and_attendance_date = sh.weekly_holiday and t.employee_no = sh.employee_no) as result_wh_shift_type_code ,TO_CHAR(sh.working_day, 'DD/MM/YYYY') AS working_day ,sh.working_day_shift_type_code ,(select t.shift_type_code from tb_att_result_n t where t.subsidiary_code = sh.subsidiary_code and t.time_and_attendance_date = sh.working_day and t.employee_no = sh.employee_no) as result_nw_shift_type_code ,sh.progress_status_code ,lgvhr_common_pkg.decode_lookup('LGCOM_APPROVAL_REQ_STATUS_CODE' ,sh.progress_status_code ,NULL ,#{USER_SESSION.languageCode}) AS approval_status ,sh.confirm_flag AS confirm_flag ,sh.approval_request_id AS request_master_id ,sh.request_code AS request_code ,lgvatt_common_pkg.get_approval_status(sh.approval_request_id ,sh.request_code ,#{LGVHR_PROJECT_SESSION.employeeNo}) AS approval_status_code ,(select local_language_full_name from lgcom_user_m where application_user_id = sh.last_update_user_id) as last_update_user_id ,TO_CHAR(sh.last_update_date, 'DD/MM/YYYY HH24:MI') as last_update_date FROM TB_ATT_SWAP_HOLIDAY_REQUEST_N sh ,emp_master em WHERE sh.subsidiary_code = em.subsidiary_code AND sh.employee_no = em.employee_number AND sh.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
AND sh.request_date BETWEEN TRUNC(TO_DATE(#{requestStartDate},'DD/MM/YYYY')) AND TRUNC(TO_DATE(#{requestEndDate},'DD/MM/YYYY')+1)
AND sh.confirm_flag = #{confirmFlag}
AND em.organization_id = #{orgId}
AND sh.employee_no like '%' || UPPER(#{empNo}) || '%'
AND UPPER(em.full_name_local) like '%' || UPPER(#{empName}) || '%'
AND sh.progress_status_code = #{approvaStatusCode}

mapper.update:
UPDATE /* LGVATT20552.applyAttSwapWhMaster */ TB_ATT_SWAP_HOLIDAY_REQUEST_N sh
   SET sh.weekly_holiday                 = TO_DATE(#{weeklyHoliday}, 'DD/MM/YYYY')
      ,sh.weekly_holiday_shift_type_code = #{weeklyHolidayShiftTypeCode}
      ,sh.working_day                    = TO_DATE(#{workingDay}, 'DD/MM/YYYY')
      ,sh.working_day_shift_type_code    = #{workingDayShiftTypeCode}
      ,sh.time_attend_input_reason_desc  = #{timeAttendInputReasonDesc}
      ,sh.confirm_flag                   = #{confirmType}
      ,sh.last_update_user_id            = #{applicationUserId}
      ,sh.last_update_date               = SYSDATE
 WHERE sh.subsidiary_code = #{subsidiaryCode}
   AND sh.employee_no = #{employeeNo}
   AND sh.approval_request_id = #{requestMasterId}
   AND sh.request_code = #{requestCode}
   AND sh.request_seq_no = #{requestSeqNo}
